"""Render a validated spec into idempotent Bash."""

from __future__ import annotations

import json
import shlex

from linuxops.spec import Spec

q = shlex.quote

HEADER = """#!/usr/bin/env bash
# Generated by linuxops from spec host={host}. Do not edit by hand; edit the spec.
# ROOT=/path/to/sandbox targets an alternate root (useradd --root); empty ROOT
# targets this host and additionally needs LINUXOPS_APPLY=yes.
set -euo pipefail
umask 027

ROOT="${{ROOT:-}}"
if [[ -z "$ROOT" && "${{LINUXOPS_APPLY:-}}" != "yes" ]]; then
  echo "refusing to touch this host: set ROOT=<sandbox> or LINUXOPS_APPLY=yes" >&2
  exit 2
fi
if [[ -n "$ROOT" && ( "$ROOT" != /* || "$ROOT" == "/" ) ]]; then
  echo "ROOT must be an absolute path other than /" >&2
  exit 2
fi
if [[ "$(id -u)" -ne 0 ]]; then
  echo "must run as root (sudo)" >&2
  exit 2
fi
ROOT_ARGS=()
if [[ -n "$ROOT" ]]; then ROOT_ARGS=(--root "$ROOT"); fi

log() {{ printf '[linuxops] %s\\n' "$*"; }}
has_group() {{ grep -q "^$1:" "$ROOT/etc/group"; }}
has_user() {{ grep -q "^$1:" "$ROOT/etc/passwd"; }}
"""


def _gid(spec: Spec, name: str) -> int:
    return spec.group_ids()[name]


def _uid(spec: Spec, name: str) -> int:
    return spec.user_ids()[name]


def sudoers_text(spec: Spec, group: str) -> str:
    rules = [r for r in spec.sudo_rules if r.group == group]
    lines = [f"# Managed by linuxops ({spec.host}). Least-privilege command list."]
    lines.append(f"Defaults:%{group} use_pty, log_output, !visiblepw")
    for r in rules:
        lines.append(f"%{group} ALL=({r.run_as}) NOEXEC: " + ", ".join(r.commands))
    return "\n".join(lines) + "\n"


def provision(spec: Spec) -> str:
    out = [HEADER.format(host=spec.host)]
    out.append("log 'groups'")
    groups = list(spec.groups)
    for u in spec.users:
        if u.primary_group == u.name and u.name not in {g.name for g in groups}:
            out.append(f'has_group {q(u.name)} || groupadd "${{ROOT_ARGS[@]}}" -g {u.uid} {q(u.name)}')
    for g in groups:
        out.append(f'has_group {q(g.name)} || groupadd "${{ROOT_ARGS[@]}}" -g {g.gid} {q(g.name)}')

    out.append("\nlog 'users (passwords locked: SSH keys / SSM only)'")
    for u in spec.users:
        gid = _gid(spec, u.primary_group)
        sec = ",".join(u.groups)
        g_flag = f" -G {q(sec)}" if sec else " -G ''"
        out.append(
            f"if has_user {q(u.name)}; then\n"
            f'  usermod "${{ROOT_ARGS[@]}}" -g {gid}{g_flag} -s {q(u.shell)} {q(u.name)}\n'
            f"else\n"
            f'  useradd "${{ROOT_ARGS[@]}}" -m -K UMASK=027 -u {u.uid} -g {gid}{g_flag}'
            f" -s {q(u.shell)} -c {q(u.comment)} {q(u.name)}\n"
            f"fi\n"
            f'usermod "${{ROOT_ARGS[@]}}" -L {q(u.name)}\n'
            f'chmod 0750 "$ROOT"/home/{q(u.name)}'
        )

    out.append("\nlog 'directories'")
    for d in spec.directories:
        out.append(
            f"install -d -m {d.mode} -o {_uid(spec, d.owner)} -g {_gid(spec, d.group)}"
            f' "$ROOT"{q(d.path)}\n'
            f'chmod {d.mode} "$ROOT"{q(d.path)}'
        )

    out.append("\nlog 'files'")
    out.append('TMP="$(mktemp)"\ntrap \'rm -f "$TMP"\' EXIT')
    for f in spec.files:
        out.append(
            f"printf '%s' {q(f.content or '')} > \"$TMP\"\n"
            f"install -m {f.mode} -o {_uid(spec, f.owner)} -g {_gid(spec, f.group)}"
            f' "$TMP" "$ROOT"{q(f.path)}'
        )

    if spec.sudo_rules:
        out.append("\nlog 'sudoers drop-ins (validated with visudo before install)'")
        out.append('install -d -m 0750 "$ROOT/etc/sudoers.d"')
        for group in dict.fromkeys(r.group for r in spec.sudo_rules):
            dest = f"/etc/sudoers.d/50-linuxops-{group}"
            out.append(
                f"printf '%s' {q(sudoers_text(spec, group))} > \"$TMP\"\n"
                f'visudo -cqf "$TMP"\n'
                f'install -m 0440 -o 0 -g 0 "$TMP" "$ROOT"{q(dest)}'
            )

    out.append("\nlog 'done'")
    return "\n".join(out) + "\n"


def teardown(spec: Spec) -> str:
    out = [HEADER.format(host=spec.host)]
    if spec.sudo_rules:
        out.append("log 'sudoers'")
        for group in dict.fromkeys(r.group for r in spec.sudo_rules):
            out.append(f'rm -f "$ROOT"{q(f"/etc/sudoers.d/50-linuxops-{group}")}')
    out.append("\nlog 'files and directories (declared paths only)'")
    for f in spec.files:
        out.append(f'rm -f "$ROOT"{q(f.path)}')
    for d in sorted(spec.directories, key=lambda e: e.path.count("/"), reverse=True):
        out.append(f'rm -rf --one-file-system "$ROOT"{q(d.path)}')
    out.append("\nlog 'users'")
    for u in spec.users:
        out.append(
            f'if has_user {q(u.name)}; then userdel "${{ROOT_ARGS[@]}}" -r {q(u.name)} 2>/dev/null || true; fi'  # noqa: E501
        )
        out.append(f'rm -rf --one-file-system "$ROOT"/home/{q(u.name)}')
    out.append("\nlog 'groups'")
    names = [g.name for g in spec.groups] + [u.name for u in spec.users if u.primary_group == u.name]
    for name in names:
        out.append(f'if has_group {q(name)}; then groupdel "${{ROOT_ARGS[@]}}" {q(name)}; fi')
    out.append("\nlog 'done'")
    return "\n".join(out) + "\n"


def fstab_line(spec: Spec, uuid: str = "<UUID>") -> str:
    v = spec.volume
    if v is None:
        raise ValueError("spec has no volume")
    return f"UUID={uuid} {v.mountpoint} {v.filesystem} {','.join(v.options)} 0 2"


def plan(spec: Spec) -> str:
    data = {
        "host": spec.host,
        "groups": {name: gid for name, gid in sorted(spec.group_ids().items())},
        "users": [
            {
                "name": u.name,
                "uid": u.uid,
                "primary_group": u.primary_group,
                "groups": list(u.groups),
                "shell": u.shell,
                "password": "locked",
            }
            for u in spec.users
        ],
        "paths": [
            {"path": e.path, "owner": e.owner, "group": e.group, "mode": e.mode}
            for e in [*spec.directories, *spec.files]
        ],
        "sudo": {r.group: list(r.commands) for r in spec.sudo_rules},
        "volume": None
        if spec.volume is None
        else {
            "label": spec.volume.label,
            "size_gib": spec.volume.size_gib,
            "fstab": fstab_line(spec),
        },
    }
    return json.dumps(data, indent=2) + "\n"
